import{_ as o,o as i,c as a,a2 as t}from"./chunks/framework.BN2sqjC1.js";const m=JSON.parse('{"title":"Checklist manuale — console admin ed export (M5)","description":"","frontmatter":{},"headers":[],"relativePath":"qa/m5-admin-export.md","filePath":"qa/m5-admin-export.md"}'),l={name:"qa/m5-admin-export.md"};function n(r,e,s,c,d,u){return i(),a("div",null,[...e[0]||(e[0]=[t('<h1 id="checklist-manuale-—-console-admin-ed-export-m5" tabindex="-1">Checklist manuale — console admin ed export (M5) <a class="header-anchor" href="#checklist-manuale-—-console-admin-ed-export-m5" aria-label="Permalink to &quot;Checklist manuale — console admin ed export (M5)&quot;">​</a></h1><p>Da eseguire contro <code>yarn dev:cloud:k3d</code> (o <code>task stack-up</code> + <code>task dev-cloud</code>) con l&#39;utente <code>admin</code> del realm di sviluppo (password <code>memobrain-dev-password</code>) e un secondo utente. Gli automatismi (<code>go test -tags integration</code>, test live Keycloak, vitest, Playwright) coprono API e flussi sul mock; qui si verifica ciò che solo l&#39;ambiente reale mostra.</p><p>Segnare <code>[x]</code> con data e sistema operativo.</p><h2 id="utenti-e-keycloak" tabindex="-1">Utenti e Keycloak <a class="header-anchor" href="#utenti-e-keycloak" aria-label="Permalink to &quot;Utenti e Keycloak&quot;">​</a></h2><ul><li>[ ] Web UI → Amministrazione → Utenti → &quot;Nuovo utente&quot; (senza password): l&#39;utente compare in Keycloak (console <code>http://localhost:8080</code>, realm <code>memobrain</code>) con azioni richieste &quot;Update Password&quot; e &quot;Verify Email&quot;.</li><li>[ ] Con password temporanea: al primo login Keycloak chiede di cambiarla; dopo il login la riga dell&#39;utente è la stessa creata dall&#39;admin (nessun duplicato).</li><li>[ ] &quot;Sospendi&quot;: l&#39;account Keycloak risulta disabilitato e le sue sessioni chiuse; l&#39;utente sospeso con un token ancora valido ottiene <code>403 USER_SUSPENDED</code> entro 30 s (subito sulla stessa replica); il desktop connesso mostra la sospensione e smette di sincronizzare.</li><li>[ ] &quot;Riattiva&quot;: può rientrare.</li><li>[ ] &quot;Reimposta password&quot;: al login successivo deve cambiarla; senza SMTP il messaggio dice che l&#39;e-mail non è stata inviata.</li><li>[ ] Ruolo → amministratore: il nuovo admin vede la voce &quot;Amministrazione&quot; dopo un nuovo login; ruolo → utente la fa sparire. L&#39;ultimo admin non si può degradare, sospendere o eliminare.</li><li>[ ] &quot;Elimina utente&quot;: i suoi vault compaiono come eliminati nel dettaglio e il login non è più possibile.</li></ul><h2 id="quota-e-limiti" tabindex="-1">Quota e limiti <a class="header-anchor" href="#quota-e-limiti" aria-label="Permalink to &quot;Quota e limiti&quot;">​</a></h2><ul><li>[ ] Quota utente = poche decine di MB: il cruscotto mostra l&#39;utente oltre le soglie; una scrittura del desktop a 100 % viene rifiutata con &quot;quota esaurita&quot;. Ripristino a &quot;predefinita&quot; riabilita le scritture.</li><li>[ ] Azione in blocco su più utenti; &quot;illimitata&quot; (-1).</li><li>[ ] Limiti di archiviazione: valori non validi (warn ≥ critical) sono rifiutati con messaggio chiaro; i nuovi valori cambiano la quota effettiva degli utenti senza override.</li></ul><h2 id="gruppi-e-profili" tabindex="-1">Gruppi e profili <a class="header-anchor" href="#gruppi-e-profili" aria-label="Permalink to &quot;Gruppi e profili&quot;">​</a></h2><ul><li>[ ] Crea gruppo, aggiungi membri (member/manager), rinomina, elimina.</li><li>[ ] Crea un profilo con <code>features.drawings=false</code> e <code>editor.fontSize</code> in <code>locked_keys</code>, assegnalo al gruppo con priorità: il desktop dei membri riceve la config (evento <code>ConfigChanged</code>), nasconde &quot;Nuovo disegno&quot; e blocca il campo. Anteprima &quot;configurazione effettiva&quot; dell&#39;utente coincide.</li><li>[ ] Modifica il profilo → la versione cresce; dalla cronologia ripristina la versione 1 (nuova versione 3).</li><li>[ ] JSON non valido o chiave sconosciuta nel profilo: errore leggibile, nessun salvataggio.</li></ul><h2 id="audit" tabindex="-1">Audit <a class="header-anchor" href="#audit" aria-label="Permalink to &quot;Audit&quot;">​</a></h2><ul><li>[ ] Le azioni precedenti compaiono con attore e target; filtro per azione (<code>user.</code>), per attore, per intervallo; &quot;Carica altro&quot; scorre le pagine.</li><li>[ ] &quot;Esporta CSV&quot; scarica un file che si apre in un foglio di calcolo senza formule inattese.</li></ul><h2 id="export-zip" tabindex="-1">Export ZIP <a class="header-anchor" href="#export-zip" aria-label="Permalink to &quot;Export ZIP&quot;">​</a></h2><ul><li>[ ] Vault <strong>condiviso</strong> (Web UI → I miei vault → &quot;Scarica ZIP&quot;): lo ZIP contiene gli stessi file del vault locale (confronto con <code>diff -r</code>, escluso <code>.memobrain/</code> device-specific).</li><li>[ ] Vault condiviso oltre 512 MB (o <code>DirectLimit</code> ridotto in dev): la UI passa al job, mostra &quot;in coda/in corso/pronto&quot; e scarica; dopo 24 h il link non funziona più.</li><li>[ ] Vault <strong>privato</strong>: dialogo passphrase → ZIP decifrato nel browser identico al vault locale; passphrase errata → errore chiaro; con recovery key funziona; nessuna richiesta all&#39;API contiene la passphrase o file in chiaro (pannello Rete del browser).</li><li>[ ] Desktop: comando &quot;Esporta vault come ZIP&quot; (palette): dialogo &quot;Salva con nome&quot;, messaggio con numero di file; lo ZIP, estratto, si apre come vault; la destinazione dentro il vault è rifiutata; annullando il dialogo non succede nulla.</li><li>[ ] Un vault privato non si esporta dal server: <code>GET /vaults/{id}/export.zip</code> risponde <code>409 VAULT_ENCRYPTED</code>.</li></ul>',13)])])}const h=o(l,[["render",n]]);export{m as __pageData,h as default};
